param([switch]$Preview, [switch]$Auto)
# Eternity 1.0 - хаб обхода блокировок: DPI (GoodbyeDPI / zapret) + DoH + TG WS Proxy + Cloudflare WARP
$ErrorActionPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [Text.Encoding]::UTF8
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
[Threading.Thread]::CurrentThread.CurrentCulture = [Globalization.CultureInfo]::InvariantCulture
try { $Host.UI.RawUI.BackgroundColor = 'Black'; $Host.UI.RawUI.WindowTitle = 'Eternity 1.0' } catch {}

$Root  = $PSScriptRoot
$Data  = Join-Path $env:ProgramData 'Eternity'          # скачанные компоненты (путь без кириллицы)
$Bin   = Join-Path $Data 'goodbyedpi'
$Zap   = Join-Path $Data 'zapret'
$TgDir = Join-Path $Data 'tgws'
$LhmDir = Join-Path $Data 'lhm'
$State = Join-Path $Root 'eternity.json'
$Version = '1.0.1'                              # версия программы (сравнивается с релизом на GitHub)
$Repo    = 'Miha1ych/Eternity'                  # репозиторий для проверки обновлений
$Task  = 'Eternity-Autostart'
$W     = 44          # ширина рамок справа (текст может выходить за правый угол, как на референсе)
$ArtW  = 62          # ширина рисунка (пересчитывается темой)
$Gap   = 8           # отступ между рисунком и панелью справа
$ShowCpuTemp = $false   # температура CPU в строке (включить, когда подключим датчик)

# ---------- палитра (truecolor): нежный розовый + салатовый ----------
# четвёртое число = жирный
$Pal = @{
    'Pink'     = 255, 166, 204
    'Pink2'    = 244, 146, 190
    'Pink3'    = 208, 120, 168
    'Red'      = 255, 112, 134
    'DarkGray' = 140, 130, 160
    'Gray'     = 208, 200, 218
    'White'    = 252, 246, 250
    'Border'   = 172, 162, 204     # рамки (как серая рамка на референсе)
    'Soft'     = 150, 232, 204     # имя
    'Title'    = 255, 196, 222
    'Dim'      = 84, 76, 106       # пустая часть баров
    'Bar1'     = 150, 232, 204     # бар: норма
    'Bar2'     = 255, 226, 150     # бар: много
    'Bar3'     = 255, 112, 134     # бар: почти полон
    'Cyan'     = 255, 148, 196, 1  # подписи Hardware/Modules (розовые, жирные)
    'Cyan2'    = 255, 226, 140, 1  # подписи Uptime/Date
    'Lab2'     = 150, 232, 204, 1  # подписи Session
    'Green'    = 150, 232, 204
    'Yellow'   = 255, 226, 150
    'Orange'   = 255, 190, 170, 1
    'dot1' = 150, 150, 160; 'dot2' = 255, 255, 255; 'dot3' = 150, 232, 204; 'dot4' = 255, 148, 196
    'dot5' = 170, 150, 255; 'dot6' = 255, 226, 140; 'dot7' = 255, 190, 170; 'dot8' = 255, 112, 134
}
Add-Type -Namespace Win -Name Vt -MemberDefinition @'
[DllImport("kernel32.dll")] public static extern IntPtr GetStdHandle(int h);
[DllImport("kernel32.dll")] public static extern bool GetConsoleMode(IntPtr h, out int m);
[DllImport("kernel32.dll")] public static extern bool SetConsoleMode(IntPtr h, int m);
'@
$h = [Win.Vt]::GetStdHandle(-11); $m = 0
if ([Win.Vt]::GetConsoleMode($h, [ref]$m)) { [void][Win.Vt]::SetConsoleMode($h, $m -bor 4) }

function Write-Host {
    param([Parameter(Position = 0)]$Object = '', [switch]$NoNewline, $ForegroundColor)
    $s = "$Object"
    if ($ForegroundColor -and $Pal.ContainsKey("$ForegroundColor")) {
        $c = $Pal["$ForegroundColor"]; $b = ''
        if ($c.Count -gt 3) { $b = "$([char]27)[1m" }
        $s = "$b$([char]27)[38;2;$($c[0]);$($c[1]);$($c[2])m$s$([char]27)[0m"
    }
    try { if ($NoNewline) { [Console]::Out.Write($s) } else { [Console]::Out.WriteLine($s) } } catch {}
}

# ---------- размер окна под тему (по замерам: ширина = самая длинная строка + запас) ----------
$WinW = 126; $WinH = 48
try {
    $th0 = (Get-Content $State -Raw -ErrorAction Stop | ConvertFrom-Json).theme
    switch ($th0) {
        'eyes' { $WinW = 150; $WinH = 48 }
        'elf'  { $WinW = 142; $WinH = 52 }
        default { $WinW = 126; $WinH = 48 }
    }
} catch {}

# ---------- админ ----------
$IsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $Preview -and -not $IsAdmin) {
    if ($Auto) { exit }
    $self = "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`""
    # через Windows Terminal: тема и прозрачность из профиля Eternity; иначе - старая консоль
    if (Get-Command wt.exe -ErrorAction SilentlyContinue) { Start-Process wt.exe -Verb RunAs -ArgumentList "--size $WinW,$WinH -p Eternity powershell.exe $self" }
    else { Start-Process powershell -Verb RunAs -ArgumentList $self }
    exit
}
if (-not $Preview -and -not $Auto) {
    try {
        $b = $Host.UI.RawUI.BufferSize; $b.Width = $WinW; $Host.UI.RawUI.BufferSize = $b
        $w = $Host.UI.RawUI.WindowSize; $w.Width = $WinW; $w.Height = $WinH; $Host.UI.RawUI.WindowSize = $w
    } catch {}
}

# ---------- состояние (eternity.json) ----------
function St-Get($k, $d = $null) {
    $o = Get-Content $State -Raw -ErrorAction SilentlyContinue | ConvertFrom-Json
    if ($o -and $o.PSObject.Properties[$k]) { $o.$k } else { $d }
}
function St-Set($k, $v) {
    $o = Get-Content $State -Raw -ErrorAction SilentlyContinue | ConvertFrom-Json
    if (-not $o) { $o = [pscustomobject]@{} }
    $o | Add-Member -NotePropertyName $k -NotePropertyValue $v -Force
    $o | ConvertTo-Json | Set-Content $State -Encoding UTF8
}

# ---------- темы ----------
# Тема = палитра (переопределяет $Pal) + рисунок + фон терминала (OSC 11, только Windows Terminal)
$PalBase = @{}; foreach ($k in $Pal.Keys) { $PalBase[$k] = $Pal[$k] }

$Themes = [ordered]@{
    'bear' = @{
        Name = 'Bear: розовый + мята'
        Bg   = '#1B1524'
        Pal  = @{}
    }
    'eyes' = @{
        Name = 'Eyes: тёмно-синий + коралл'
        Bg   = '#232B3A'
        Pal  = @{
            'Pink' = 224, 93, 118;  'Pink2' = 224, 93, 118;  'Pink3' = 190, 80, 104
            'Red' = 255, 105, 125;  'DarkGray' = 118, 128, 150;  'Gray' = 190, 198, 216;  'White' = 236, 239, 248
            'Border' = 104, 116, 142;  'Soft' = 250, 160, 178;  'Title' = 200, 206, 224;  'Dim' = 66, 76, 98
