            'Green' = 134, 214, 186;  'Yellow' = 255, 204, 150;  'Orange' = 255, 170, 186, 1
            'dot1' = 118, 128, 150; 'dot2' = 236, 239, 248; 'dot3' = 134, 214, 186; 'dot4' = 224, 93, 118
            'dot5' = 120, 150, 230; 'dot6' = 255, 204, 150; 'dot7' = 160, 210, 160; 'dot8' = 255, 105, 125
        }
    }
    'elf' = @{
        Name = 'Elf: сливовый + лайм/мята'
        Bg   = '#1F1A2B'
        Pal  = @{
            'Pink' = 240, 176, 172;  'Pink2' = 232, 150, 150;  'Pink3' = 200, 120, 130
            'Red' = 255, 120, 130;  'DarkGray' = 128, 120, 150;  'Gray' = 205, 200, 215;  'White' = 244, 240, 235
            'Border' = 125, 115, 150;  'Soft' = 214, 226, 150;  'Title' = 225, 225, 190;  'Dim' = 70, 62, 92
            'Bar1' = 188, 214, 110;  'Bar2' = 245, 196, 120;  'Bar3' = 240, 110, 125
            'Cyan' = 196, 222, 120, 1;  'Cyan2' = 140, 226, 204, 1;  'Lab2' = 214, 226, 150, 1
            'Green' = 140, 226, 190;  'Yellow' = 245, 215, 140;  'Orange' = 240, 176, 172, 1
            'dot1' = 128, 120, 150; 'dot2' = 244, 240, 235; 'dot3' = 140, 226, 204; 'dot4' = 240, 176, 172
            'dot5' = 214, 226, 150; 'dot6' = 245, 215, 140; 'dot7' = 170, 150, 220; 'dot8' = 255, 120, 130
        }
    }
    'duo' = @{
        Name = 'Redhead: красный + золото'
        Bg   = '#0F1512'
        Pal  = @{
            'Pink' = 240, 170, 160;  'Pink2' = 225, 140, 135;  'Pink3' = 190, 110, 110
            'Red' = 225, 60, 70;  'DarkGray' = 120, 130, 120;  'Gray' = 205, 205, 195;  'White' = 240, 236, 226
            'Border' = 110, 130, 112;  'Soft' = 150, 200, 140;  'Title' = 220, 214, 190;  'Dim' = 60, 74, 64
            'Bar1' = 70, 170, 100;  'Bar2' = 240, 190, 70;  'Bar3' = 225, 60, 70
            'Cyan' = 240, 190, 70, 1;  'Cyan2' = 225, 75, 85, 1;  'Lab2' = 90, 200, 120, 1
            'Green' = 90, 200, 120;  'Yellow' = 240, 190, 70;  'Orange' = 240, 190, 70, 1
            'dot1' = 120, 130, 120; 'dot2' = 240, 236, 226; 'dot3' = 70, 170, 100; 'dot4' = 225, 60, 70
            'dot5' = 130, 130, 200; 'dot6' = 240, 190, 70; 'dot7' = 150, 100, 60; 'dot8' = 240, 170, 160
        }
    }
}

function Get-ThemeKey { $k = "$(St-Get 'theme' 'bear')"; if ($Themes.Contains($k)) { $k } else { 'bear' } }

# цвет фона терминала (OSC 11 / 111) - работает в Windows Terminal, в старой консоли пропускаем
function Set-TermBg($hex) {
    if (-not $env:WT_SESSION) { return }
    $e = [char]27
    try {
        if ($hex) { [Console]::Out.Write("$e]11;$hex$e\") } else { [Console]::Out.Write("$e]111$e\") }
    } catch {}
}

function Apply-Theme {
    $k = Get-ThemeKey
    foreach ($n in $PalBase.Keys) { $script:Pal[$n] = $PalBase[$n] }
    foreach ($n in $Themes[$k].Pal.Keys) { $script:Pal[$n] = $Themes[$k].Pal[$n] }
    foreach ($n in @($script:Pal.Keys)) { $c = $script:Pal[$n]; if ($c.Count -gt 3) { $script:Pal["${n}_n"] = @($c[0], $c[1], $c[2]) } }
    $script:Art = switch ($k) { 'eyes' { $ArtEyes } 'elf' { $ArtElf } 'duo' { $ArtDuo } default { $ArtBear } }
    $script:ArtW = ($script:Art | ForEach-Object { VLen $_ } | Measure-Object -Maximum).Maximum
    Set-TermBg $Themes[$k].Bg
}

function Switch-Theme {
    $keys = @($Themes.Keys)
    $i = [array]::IndexOf($keys, (Get-ThemeKey))
    $new = $keys[($i + 1) % $keys.Count]
    St-Set 'theme' $new
    Apply-Theme
    Write-Host "  ✓ тема: $($Themes[$new].Name)" -ForegroundColor Green
}


$Modes = @{
    '5' = @('-5', '-q')   # фрагментация + fake + авто-TTL, блок QUIC (YouTube уходит на TCP)
    '9' = @('-9', '-q')   # агрессивный: wrong-chksum/seq, если 5 не помогает
}
function Get-Mode { $m = "$(St-Get 'mode' '5')"; if ($Modes.ContainsKey($m)) { $m } else { '5' } }
function Get-EngineName { if ((St-Get 'engine' 'goodbyedpi') -eq 'zapret') { 'zapret' } else { 'goodbyedpi' } }

