$Art = $ArtBear

function VLen([string]$s) { ($s -replace "\x1b\[[0-9;]*m", '').Length }

function Write-Art([string]$line) {
    if ($line.Contains([string][char]27)) { Write-Host $line -NoNewline; return }
    $i = 0
    while ($i -lt $line.Length) {
        $c = $line[$i]
        $col = switch -Regex ($c) { '[#%@]' { 'Pink' } '[*+]' { 'Pink2' } '[X/\\]' { 'Red' } '[=\-:.]' { 'Pink3' } '[\u2800-\u28FF\u2580-\u259F]' { 'Pink' } default { 'Gray' } }
        $j = $i
        while ($j -lt $line.Length -and $line[$j] -eq $c) { $j++ }
        Write-Host $line.Substring($i, $j - $i) -NoNewline -ForegroundColor $col
        $i = $j
    }
}

# ---------- рендер: сегменты, рамки, бары ----------
function S($t, $c = 'Gray') { ,@($t, $c) }
function Ln { ,$args }
function Row($l, $v, $c = 'White') { [pscustomobject]@{ L = $l; V = $v; C = $c } }

function BarSegs([double]$p, [int]$w = 14, [switch]$NoPct) {
    $f = [int][math]::Round($p / 100 * $w); if ($f -gt $w) { $f = $w }
    $col = if ($p -lt 60) { 'Bar1' } elseif ($p -lt 85) { 'Bar2' } else { 'Bar3' }
    $o = New-Object System.Collections.ArrayList
    $null = $o.Add((S ' [' 'Border'))
    if ($f -gt 0)  { $null = $o.Add((S ('■' * $f) $col)) }
    if ($f -lt $w) { $null = $o.Add((S ('·' * ($w - $f)) 'Dim')) }
    $null = $o.Add((S '] ' 'Border'))
    if (-not $NoPct) { $null = $o.Add((S ('{0}%' -f [int]$p) 'White')) }
    $o
}
function WithBar($text, $p) {
    $o = New-Object System.Collections.ArrayList
    $null = $o.Add((S $text 'White'))
    $o.AddRange($(BarSegs $p))
    , $o
}
function Gib($b) { '{0:N2}' -f ($b / 1GB) }

# рамка 1 в 1 как на референсе: серый каркас, а тик "├─", заголовок и подпись окрашены цветом секции
#   ┌──────── Hardware ────────┐
#   ├─ CPU        значение
#   └──────────────────────────┘
function Box($title, $rows, $lc = 'Cyan', $w = 45) {
    $inner = $w - 2
    $t = " $title "
    $l = [int][math]::Floor(($inner - $t.Length) / 2); $r = $inner - $t.Length - $l
    $ac = "${lc}_n"                                    # тот же цвет, но без жирного
    $o = New-Object System.Collections.ArrayList
    $null = $o.Add((Ln (S ('┌' + ('─' * $l)) 'Border') (S $t $ac) (S (('─' * $r) + '┐') 'Border')))
    foreach ($x in $rows) {
        $parts = New-Object System.Collections.ArrayList
        $null = $parts.Add((S '├─' $ac)); $null = $parts.Add((S ' ' 'Gray')); $null = $parts.Add((S $x.L.PadRight(11) $lc))
        if ($x.V -is [string]) { $null = $parts.Add((S $x.V $x.C)) } else { $parts.AddRange($x.V) }
        $null = $o.Add($parts.ToArray())
    }
    $null = $o.Add((Ln (S ('└' + ('─' * $inner) + '┘') 'Border')))
    $o
}
# =====================================================================
#  МОДУЛЬ: DPI (GoodbyeDPI / zapret)
# =====================================================================
function Test-Running { [bool](Get-Process goodbyedpi, winws -ErrorAction SilentlyContinue) }
function Get-Engine { Get-ChildItem $Bin -Recurse -Filter goodbyedpi.exe -ErrorAction SilentlyContinue | Where-Object FullName -match 'x86_64' | Select-Object -First 1 }
function Get-ZapDir { $b = Get-ChildItem $Zap -Recurse -Filter 'service.bat' -ErrorAction SilentlyContinue | Select-Object -First 1; if ($b) { $b.DirectoryName } }
function Get-Strategies { $d = Get-ZapDir; if ($d) { Get-ChildItem $d -Filter 'general*.bat' | Sort-Object Name } }

function Get-Release($repo) { Invoke-RestMethod "https://api.github.com/repos/$repo/releases/latest" -Headers @{ 'User-Agent' = 'Eternity' } }

function Install-Engine {
    Write-Host '  » ищу последнюю сборку GoodbyeDPI на GitHub...' -ForegroundColor Soft
    $rel = Invoke-RestMethod 'https://api.github.com/repos/ValdikSS/GoodbyeDPI/releases' -Headers @{ 'User-Agent' = 'Eternity' }
    $asset = $rel | ForEach-Object { $_.assets } | Where-Object name -like 'goodbyedpi*.zip' | Select-Object -First 1
    if (-not $asset) { Write-Host '  ✗ не удалось получить релиз (GitHub недоступен?)' -ForegroundColor Red; return $false }
    $zip = Join-Path $env:TEMP $asset.name
    Write-Host "  » качаю $($asset.name)" -ForegroundColor Soft
    Invoke-WebRequest $asset.browser_download_url -OutFile $zip -UseBasicParsing
    Stop-Bypass -Quiet
    if (Test-Path $Bin) { Remove-Item $Bin -Recurse -Force }
    New-Item -ItemType Directory -Path $Bin -Force | Out-Null
    Expand-Archive $zip -DestinationPath $Bin -Force
    Remove-Item $zip -Force
    if (Get-Engine) { Write-Host '  ✓ GoodbyeDPI установлен' -ForegroundColor Green; return $true }
    Write-Host '  ✗ goodbyedpi.exe не найден в архиве' -ForegroundColor Red
    $false
}

# zapret (Flowseal/zapret-discord-youtube): набор стратегий winws
function Install-Zapret {
    Write-Host '  » качаю zapret-discord-youtube (Flowseal) с GitHub...' -ForegroundColor Soft
    $rel = Get-Release 'Flowseal/zapret-discord-youtube'
    $asset = $rel.assets | Where-Object name -like '*.zip' | Select-Object -First 1
    if (-not $asset) { Write-Host '  ✗ не удалось получить релиз (GitHub недоступен?)' -ForegroundColor Red; return $false }
    $zip = Join-Path $env:TEMP $asset.name
    Invoke-WebRequest $asset.browser_download_url -OutFile $zip -UseBasicParsing
    Stop-Bypass -Quiet
    if (Test-Path $Zap) { Remove-Item $Zap -Recurse -Force }
    New-Item -ItemType Directory -Path $Zap -Force | Out-Null
    Expand-Archive $zip -DestinationPath $Zap -Force
    Remove-Item $zip -Force
    Get-ChildItem $Zap -Recurse -File | Unblock-File
    if (Get-ZapDir) { Write-Host "  ✓ zapret установлен ($($asset.name))" -ForegroundColor Green; return $true }
    Write-Host '  ✗ service.bat не найден в архиве' -ForegroundColor Red
    $false
}

function Start-Zapret($bat) {
    Stop-Bypass -Quiet
    Start-Process cmd.exe -ArgumentList "/c call `"$($bat.Name)`"" -WorkingDirectory $bat.DirectoryName -WindowStyle Hidden
    Start-Sleep 4
}

function Test-Web($h, $t = 8) {
    $code = & curl.exe -s -o NUL -m $t --connect-timeout 5 -w '%{http_code}' "https://$h"
    ("$code" -match '^\d{3}$') -and ("$code" -ne '000')
}

function Find-Strategy {
    if (-not (Get-ZapDir)) { if (-not (Install-Zapret)) { return } }
    $list = @(Get-Strategies)
    if (-not $list.Count) { Write-Host '  ✗ в архиве нет general*.bat' -ForegroundColor Red; return }
    Disable-Warp -Quiet
    Write-Host "  » перебираю стратегии ($($list.Count)), критерий - открывается youtube.com" -ForegroundColor Soft
    $i = 0
    foreach ($b in $list) {
        $i++
        Write-Host ('  [{0,2}/{1}] {2,-36}' -f $i, $list.Count, $b.Name) -NoNewline -ForegroundColor Gray
        Start-Zapret $b
        if (Test-Web 'www.youtube.com') {
            Write-Host 'работает' -ForegroundColor Green
            St-Set 'strategy' $b.Name; St-Set 'engine' 'zapret'; St-Set 'want_dpi' $true
            Write-Host '  ✓ стратегия сохранена, обход запущен' -ForegroundColor Green
            return
        }
        Write-Host 'нет' -ForegroundColor DarkGray
        Stop-Bypass -Quiet
    }
    Write-Host '  ✗ ни одна стратегия не сработала (проверь DNS: пункт 2, и антивирус)' -ForegroundColor Red
}

function Start-Bypass {
    Disable-Warp -Quiet     # DPI-обход и WARP взаимоисключающие
    if ((Get-EngineName) -eq 'zapret') {
        if (-not (Get-ZapDir)) { if (-not (Install-Zapret)) { return } }
        $name = St-Get 'strategy'
        $b = Get-Strategies | Where-Object Name -eq $name | Select-Object -First 1
        if (-not $b) { Find-Strategy; return }
        Start-Zapret $b
        if (Test-Running) { Write-Host "  ✓ zapret запущен [$name]" -ForegroundColor Green; St-Set 'want_dpi' $true }
        else { Write-Host '  ✗ winws не запустился: антивирус мог удалить WinDivert/winws.exe' -ForegroundColor Red }
        return
    }
    $e = Get-Engine
    if (-not $e) { if (-not (Install-Engine)) { return }; $e = Get-Engine; if (-not $e) { return } }
    Stop-Bypass -Quiet
    Start-Process $e.FullName -ArgumentList $Modes[(Get-Mode)] -WorkingDirectory $e.DirectoryName -WindowStyle Hidden
    Start-Sleep 2
    if (Test-Running) { Write-Host "  ✓ обход запущен (goodbyedpi, режим -$(Get-Mode))" -ForegroundColor Green; St-Set 'want_dpi' $true }
    else { Write-Host '  ✗ не запустился: антивирус мог удалить WinDivert - добавь C:\ProgramData\Eternity в исключения' -ForegroundColor Red }
}

function Stop-Bypass([switch]$Quiet) {
    Get-Process goodbyedpi, winws -ErrorAction SilentlyContinue | Stop-Process -Force
    if (-not $Quiet) { Write-Host '  ✓ DPI-обход остановлен' -ForegroundColor Yellow }
}

