$DnsProviders = [ordered]@{
    'cloudflare' = @{ Name = 'Cloudflare'; Servers = @('1.1.1.1', '1.0.0.1');               Doh = 'https://cloudflare-dns.com/dns-query' }
    'bezmezhau'  = @{ Name = 'Bezmezhau';  Servers = @('143.20.64.55', '31.58.216.201');    Doh = $null }
    'xbox'       = @{ Name = 'Xbox DNS';   Servers = @('111.88.96.54', '111.88.96.55');     Doh = $null }
    'comss'      = @{ Name = 'Comss.one';  Servers = @('83.220.169.155', '212.109.195.93'); Doh = 'https://dns.comss.one/dns-query' }
    'adguard'    = @{ Name = 'AdGuard';    Servers = @('94.140.14.14', '94.140.15.15');     Doh = 'https://dns.adguard-dns.com/dns-query' }
}

# ключ активного провайдера (по основному адресу на активных адаптерах) или $null
function Get-DnsKey {
    $cur = @()
    foreach ($x in (Get-NetAdapter | Where-Object Status -eq 'Up')) {
        $cur += @((Get-DnsClientServerAddress -InterfaceIndex $x.ifIndex -AddressFamily IPv4).ServerAddresses)
    }
    foreach ($k in $DnsProviders.Keys) {
        if ($cur -contains $DnsProviders[$k].Servers[0]) { return $k }
    }
    $null
}

function Test-DohRegistered($ip) {
    [bool]((Get-Command Get-DnsClientDohServerAddress -ErrorAction SilentlyContinue) -and (Get-DnsClientDohServerAddress | Where-Object ServerAddress -eq $ip))
}

# 'doh' - активный провайдер с зарегистрированным DoH, 'plain' - без шифрования, 'system' - не наш DNS
function Get-DnsState {
    $k = Get-DnsKey
    if (-not $k) { return 'system' }
    if (Test-DohRegistered $DnsProviders[$k].Servers[0]) { 'doh' } else { 'plain' }
}

function Set-Dns([string]$Key) {
    $pr = $DnsProviders[$Key]
    if (-not $pr) { Write-Host "  ✗ неизвестный DNS: $Key" -ForegroundColor Red; return }
    $encrypted = $false
    if ($pr.Doh) {
        if (Get-Command Add-DnsClientDohServerAddress -ErrorAction SilentlyContinue) {
            foreach ($ip in $pr.Servers) {
                Add-DnsClientDohServerAddress -ServerAddress $ip -DohTemplate $pr.Doh -AllowFallbackToUdp $true -AutoUpgrade $true -ErrorAction SilentlyContinue
            }
            $encrypted = $true
        } else {
            Write-Host '  ! эта Windows не умеет системный DoH (нужна Windows 11 или Win10 22H2+) - будет обычный DNS без шифрования.' -ForegroundColor Yellow
            Write-Host '    Зашифровать запросы можно "Безопасным DNS" в браузере.' -ForegroundColor DarkGray
        }
    }
    foreach ($a in (Get-NetAdapter | Where-Object Status -eq 'Up')) {
        Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses $pr.Servers
    }
    Clear-DnsClientCache
    Start-Sleep 2
    if (-not (Resolve-DnsName 'example.com' -Type A -DnsOnly -ErrorAction SilentlyContinue)) {
        foreach ($a in (Get-NetAdapter | Where-Object Status -eq 'Up')) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ResetServerAddresses }
        Clear-DnsClientCache
        Write-Host "  ✗ $($pr.Name) не отвечает - вернул прежний DNS, чтобы не остаться без интернета" -ForegroundColor Red
        return
    }
    St-Set 'dns_provider' $Key; St-Set 'want_dns' $true
    $ips = $pr.Servers -join ' / '
    if ($encrypted -and (Test-DohRegistered $pr.Servers[0])) { Write-Host "  ✓ DNS: $($pr.Name) ($ips), запросы зашифрованы (DoH)" -ForegroundColor Green }
    elseif ($pr.Doh) { Write-Host "  ! DNS: $($pr.Name) ($ips) выставлен, но DoH не зарегистрировался - запросы идут без шифрования" -ForegroundColor Yellow }
    else { Write-Host "  ✓ DNS: $($pr.Name) ($ips). Обычный DNS без шифрования - провайдер видит и может менять запросы" -ForegroundColor Green }
}

# совместимость со старыми вызовами
function Set-DoH { Set-Dns (St-Get 'dns_provider' 'cloudflare') }

function Reset-DNS([switch]$Quiet) {
    foreach ($a in (Get-NetAdapter)) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ResetServerAddresses }
    if (Get-Command Remove-DnsClientDohServerAddress -ErrorAction SilentlyContinue) {
        foreach ($pr in $DnsProviders.Values) {
            foreach ($ip in $pr.Servers) { Remove-DnsClientDohServerAddress -ServerAddress $ip -ErrorAction SilentlyContinue }
        }
    }
    Clear-DnsClientCache
    if (-not $Quiet) { Write-Host '  ✓ DNS сброшен на автоматический' -ForegroundColor Yellow }
}

# меню выбора DNS
function Choose-Dns {
    $cur = Get-DnsKey
    Write-Host '  Выбор DNS:' -ForegroundColor Title
    $i = 0; $keys = @()
    foreach ($k in $DnsProviders.Keys) {
        $i++; $keys += $k
        $pr = $DnsProviders[$k]
        $mark = if ($k -eq $cur) { '  ← активен' } else { '' }
        $enc = if ($pr.Doh) { 'DoH' } else { 'обычный' }
        Write-Host ('   [{0}] {1,-12} {2,-32} {3,-8}{4}' -f $i, $pr.Name, ($pr.Servers -join ' / '), $enc, $mark) -ForegroundColor Gray
    }
    Write-Host '   [0] Сбросить на автоматический DNS' -ForegroundColor Gray
    Write-Host '  Номер (Enter - отмена): ' -NoNewline -ForegroundColor Yellow
    $c = ([Console]::ReadLine()).Trim()
    if ($c -eq '') { return }
    if ($c -eq '0') { Reset-DNS; St-Set 'want_dns' $false; return }
    $n = 0
    if ([int]::TryParse($c, [ref]$n) -and $n -ge 1 -and $n -le $keys.Count) { Set-Dns $keys[$n - 1] }
    else { Write-Host '  ? нет такого пункта' -ForegroundColor DarkGray }
}

