function Start-CurlProbe([string]$hostName, [string]$ip) {
    $a = @('-s', '-o', 'NUL', '--connect-timeout', '4', '-m', '7', '-w', '"%{http_code} %{time_total}"')
    if ($ip) { $a += @('--resolve', "${hostName}:443:$ip") }
    $a += "https://$hostName"
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = 'curl.exe'
    $psi.Arguments = $a -join ' '
    $psi.RedirectStandardOutput = $true
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    [System.Diagnostics.Process]::Start($psi)
}

function Find-BestDns {
    $cands = @([pscustomobject]@{ Key = 'system'; Name = 'Текущий (система)'; Server = $null })
    foreach ($k in $DnsProviders.Keys) {
        $cands += [pscustomobject]@{ Key = $k; Name = $DnsProviders[$k].Name; Server = $DnsProviders[$k].Servers[0] }
    }
    $dpi = if (Test-Running) { 'ВКЛ' } else { 'выкл' }
    Write-Host "  Автоподбор DNS: проверяю $($DnsTestSites.Count) сайтов у $($cands.Count) вариантов (DPI-обход: $dpi)." -ForegroundColor Soft
    Write-Host '  Критерии: резолвится ли домен, открывается ли HTTPS по полученному адресу, скорость.' -ForegroundColor DarkGray
    Write-Host '  Замер идёт при текущем состоянии DPI-обхода - для честного результата включи его заранее (пункт 1).' -ForegroundColor DarkGray
    Write-Host ''

    $results = @()
    $n = 0
    foreach ($c in $cands) {
        $n++
        Write-Host ('  [{0}/{1}] {2,-20}' -f $n, $cands.Count, $c.Name) -NoNewline -ForegroundColor Gray
        $probes = @()
        foreach ($label in $DnsTestSites.Keys) {
            $domain = $DnsTestSites[$label]
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            if ($c.Server) { $r = Resolve-DnsName $domain -Type A -DnsOnly -Server $c.Server -QuickTimeout -ErrorAction SilentlyContinue }
            else { $r = Resolve-DnsName $domain -Type A -DnsOnly -QuickTimeout -ErrorAction SilentlyContinue }
            $sw.Stop()
            $ip = ($r | Where-Object { $_.Type -eq 'A' -and $_.IPAddress } | Select-Object -First 1).IPAddress
            $p = $null
            if ($ip) { $p = Start-CurlProbe $domain $(if ($c.Server) { $ip } else { $null }) }
            $probes += [pscustomobject]@{ Label = $label; Ip = $ip; DnsMs = $sw.ElapsedMilliseconds; Proc = $p; Ok = $false; Total = $null }
        }
        foreach ($pr in $probes) {
            if ($pr.Proc) {
                $out = $pr.Proc.StandardOutput.ReadToEnd()
                [void]$pr.Proc.WaitForExit(9000)
                if ("$out".Trim() -match '^(\d{3})\s+([\d\.,]+)') {
                    $pr.Ok = ($Matches[1] -ne '000')
                    $pr.Total = [double]::Parse(($Matches[2] -replace ',', '.'), [Globalization.CultureInfo]::InvariantCulture) * 1000
                }
            }
        }
        $okCount = @($probes | Where-Object Ok).Count
        $dnsAvg = [int](($probes | Where-Object Ip | Measure-Object DnsMs -Average).Average)
        $totAvg = [int](($probes | Where-Object Ok | Measure-Object Total -Average).Average)
        $results += [pscustomobject]@{ Key = $c.Key; Name = $c.Name; Ok = $okCount; Total = $probes.Count; DnsAvg = $dnsAvg; TotAvg = $totAvg; Probes = $probes }
        $col = if ($okCount -eq $probes.Count) { 'Green' } elseif ($okCount -ge [math]::Ceiling($probes.Count / 2)) { 'Yellow' } else { 'Red' }
        Write-Host ('{0}/{1}' -f $okCount, $probes.Count) -ForegroundColor $col
    }

    # итог: больше открывшихся сайтов, при равенстве - быстрее отклик
    $best = $results | Sort-Object @{ Expression = 'Ok'; Descending = $true }, @{ Expression = { if ($_.TotAvg -gt 0) { $_.TotAvg } else { 99999 } } } | Select-Object -First 1
    Write-Host ''
    Write-Host ('  {0,-20} {1,-7} {2,-9} {3,-10} {4}' -f 'DNS', 'сайты', 'DNS мс', 'отклик мс', ($DnsTestSites.Keys -join ' ')) -ForegroundColor Title
    foreach ($r in ($results | Sort-Object @{ Expression = 'Ok'; Descending = $true }, TotAvg)) {
        $labels = @($DnsTestSites.Keys)
        $marks = (0..($r.Probes.Count - 1) | ForEach-Object {
            $pb = $r.Probes[$_]
            $m = if ($pb.Ok) { '✓' } elseif ($pb.Ip) { '✗' } else { '·' }
            $m.PadRight($labels[$_].Length)
        }) -join ' '
        $col = if ($r.Key -eq $best.Key) { 'Green' } else { 'Gray' }
        $star = if ($r.Key -eq $best.Key) { ' ★' } else { '' }
        Write-Host ('  {0,-20} {1,-7} {2,-9} {3,-10} {4}{5}' -f $r.Name, "$($r.Ok)/$($r.Total)", $r.DnsAvg, $r.TotAvg, $marks, $star) -ForegroundColor $col
    }
    Write-Host '  ✓ открылся   ✗ адрес получен, но HTTPS не прошёл (блок по IP/DPI)   · домен не резолвится' -ForegroundColor DarkGray
    Write-Host ''

    if ($best.Key -eq 'system') {
        Write-Host '  Лучший вариант - текущий DNS системы, менять ничего не нужно.' -ForegroundColor Green
        return
    }
    if ($best.Ok -eq 0) {
        Write-Host '  Ни один DNS не открыл сайты - дело не в DNS, а в блокировке по SNI/IP. Включи DPI-обход (пункт 1/5) или WARP.' -ForegroundColor Yellow
        return
    }
    Write-Host "  Лучший: $($best.Name) ($($best.Ok)/$($best.Total), отклик $($best.TotAvg) мс). Применить? [Y/n] " -NoNewline -ForegroundColor Yellow
    if (([Console]::ReadLine()) -notmatch '^(n|н)') { Set-Dns $best.Key }
}

# =====================================================================
#  МОДУЛЬ: TG WS Proxy (Flowseal/tg-ws-proxy) - локальный MTProto-прокси 127.0.0.1:1443
# =====================================================================
function Get-TgExe { Get-ChildItem $TgDir -Filter 'TgWsProxy*.exe' -ErrorAction SilentlyContinue | Select-Object -First 1 }
function Test-Tg { [bool](Get-Process -Name 'TgWsProxy*' -ErrorAction SilentlyContinue) }

function Install-Tg {
    Write-Host '  » качаю TG WS Proxy (Flowseal) с GitHub...' -ForegroundColor Soft
    $rel = Get-Release 'Flowseal/tg-ws-proxy'
    $name = if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64') { 'TgWsProxy_windows_arm64.exe' } else { 'TgWsProxy_windows.exe' }
    $asset = $rel.assets | Where-Object name -eq $name | Select-Object -First 1
    if (-not $asset) { Write-Host '  ✗ не удалось получить релиз (GitHub недоступен?)' -ForegroundColor Red; return $false }
    Stop-Tg -Quiet
    New-Item -ItemType Directory -Path $TgDir -Force | Out-Null
    New-Item -ItemType Directory -Path (Join-Path $TgDir 'TgWsProxy_data') -Force | Out-Null   # портативный режим: конфиг лежит рядом
    $dst = Join-Path $TgDir $name
    Invoke-WebRequest $asset.browser_download_url -OutFile $dst -UseBasicParsing
    Unblock-File $dst
    if (Test-Path $dst) { Write-Host "  ✓ TG WS Proxy установлен ($($rel.tag_name))" -ForegroundColor Green; return $true }
    $false
}

function Get-TgLink {
    $cfg = Get-ChildItem (Join-Path $TgDir 'TgWsProxy_data') -Filter '*.json' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $cfg) { $cfg = Get-ChildItem (Join-Path $env:APPDATA 'TgWsProxy') -Filter '*.json' -ErrorAction SilentlyContinue | Select-Object -First 1 }
    if (-not $cfg) { return $null }
    $j = Get-Content $cfg.FullName -Raw | ConvertFrom-Json
    if (-not $j.secret) { return $null }
    $srv = if ($j.host) { $j.host } else { '127.0.0.1' }; $port = if ($j.port) { $j.port } else { 1443 }
    $sec = "$($j.secret)"; if ($sec -match '^[0-9a-fA-F]{32}$') { $sec = 'dd' + $sec }
    "tg://proxy?server=$srv&port=$port&secret=$sec"
}

function Open-TgLink {
    $l = Get-TgLink
    if ($l) { Start-Process $l; Write-Host '  ✓ отправил ссылку в Telegram - нажми "Подключить прокси"' -ForegroundColor Green; St-Set 'tg_linked' $true }
    else {
        Write-Host '  ! ссылку собрать не удалось. Правый клик по иконке TG WS Proxy в трее ->' -ForegroundColor Yellow
        Write-Host '    "Открыть в Telegram" (или "Скопировать ссылку").' -ForegroundColor Yellow
    }
}

function Start-Tg {
    if (-not (Get-TgExe)) { if (-not (Install-Tg)) { return } }
    $exe = Get-TgExe
    if (Test-Tg) { Write-Host '  ✓ TG WS Proxy уже запущен' -ForegroundColor Green; return }
    Start-Process $exe.FullName -WorkingDirectory $TgDir
    Start-Sleep 3
    if (Test-Tg) {
        Write-Host '  ✓ TG WS Proxy запущен (127.0.0.1:1443, значок в трее)' -ForegroundColor Green
        St-Set 'want_tg' $true
        if (-not $Auto -and -not (St-Get 'tg_linked' $false)) { Open-TgLink }
    } else { Write-Host '  ✗ TG WS Proxy не запустился' -ForegroundColor Red }
}

function Stop-Tg([switch]$Quiet) {
    Get-Process -Name 'TgWsProxy*' -ErrorAction SilentlyContinue | Stop-Process -Force
    if (-not $Quiet) { Write-Host '  ✓ TG WS Proxy остановлен' -ForegroundColor Yellow }
}

# =====================================================================
#  МОДУЛЬ: Cloudflare WARP (официальный клиент, управление через warp-cli)
# =====================================================================
function Get-WarpCli {
    $c = Get-Command warp-cli.exe -ErrorAction SilentlyContinue
    if ($c) { return $c.Source }
    foreach ($p in "$env:ProgramFiles\Cloudflare\Cloudflare WARP\warp-cli.exe", "${env:ProgramFiles(x86)}\Cloudflare\Cloudflare WARP\warp-cli.exe") { if (Test-Path $p) { return $p } }
}
# 'none' - не установлен, 'on' - подключён, 'off' - отключён
function Get-WarpState {
    $c = Get-WarpCli
    if (-not $c) { return 'none' }
    $s = (& $c status | Out-String)
    if ($s -cmatch '\bConnected\b') { 'on' } else { 'off' }
}

function Install-Warp {
    if (-not (Get-Command winget.exe -ErrorAction SilentlyContinue)) {
        Write-Host '  ✗ нет winget. Скачай клиент вручную: https://1.1.1.1/ (Cloudflare WARP для Windows) и запусти пункт снова.' -ForegroundColor Red
        return $false
    }
    Write-Host '  » устанавливаю официальный Cloudflare WARP через winget (Cloudflare.Warp)...' -ForegroundColor Soft
    & winget.exe install --id Cloudflare.Warp -e --silent --accept-package-agreements --accept-source-agreements | Out-Null
    Start-Sleep 5
    if (Get-WarpCli) { Write-Host '  ✓ WARP установлен' -ForegroundColor Green; return $true }
    Write-Host '  ✗ не удалось установить WARP автоматически, поставь вручную: https://1.1.1.1/' -ForegroundColor Red
    $false
}

function Enable-Warp {
    if (-not (Get-WarpCli)) {
        Write-Host '  WARP не установлен. Установить официальный клиент Cloudflare? [y/N] ' -NoNewline -ForegroundColor Yellow
        if (([Console]::ReadLine()) -notmatch '^(y|д)') { return }
        if (-not (Install-Warp)) { return }
    }
    $c = Get-WarpCli
    if (Test-Running) { Stop-Bypass -Quiet; Write-Host '  » DPI-обход остановлен (WARP и DPI вместе не работают)' -ForegroundColor DarkGray }
    $st = (& $c status | Out-String)
    if ($st -match 'egistration') {
        Write-Host '  » регистрирую WARP...' -ForegroundColor Soft
        $o = (& $c --accept-tos registration new | Out-String)
        if ($o -match 'rror|nrecognized|nknown') { & $c --accept-tos register | Out-Null }
    }
    & $c --accept-tos connect | Out-Null
    for ($i = 0; $i -lt 10; $i++) { Start-Sleep 1; if ((Get-WarpState) -eq 'on') { break } }
    if ((Get-WarpState) -eq 'on') { Write-Host '  ✓ WARP подключён' -ForegroundColor Green; St-Set 'want_warp' $true; St-Set 'want_dpi' $false }
    else { Write-Host '  ✗ WARP не подключился (в РФ его эндпоинты часто режутся). Попробуй DPI-обход.' -ForegroundColor Red }
}

function Disable-Warp([switch]$Quiet) {
    $c = Get-WarpCli
    if (-not $c) { return }
    if ((Get-WarpState) -ne 'on') { return }
    & $c disconnect | Out-Null
    if (-not $Quiet) { Write-Host '  ✓ WARP отключён' -ForegroundColor Yellow } else { Write-Host '  » WARP отключён (с DPI-обходом несовместим)' -ForegroundColor DarkGray }
    St-Set 'want_warp' $false
}

# =====================================================================
#  Автозапуск (планировщик задач, без UAC при входе)
# =====================================================================
function Test-Autostart { [bool](Get-ScheduledTask -TaskName $Task -ErrorAction SilentlyContinue) }
function Set-Autostart([bool]$on) {
    if ($on) {
        $user = "$env:USERDOMAIN\$env:USERNAME"
        $a  = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Auto"
        $tr = New-ScheduledTaskTrigger -AtLogOn -User $user
        $tr.Delay = 'PT20S'
        $pr = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Highest
        $se = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit ([TimeSpan]::Zero)
        Register-ScheduledTask -TaskName $Task -Action $a -Trigger $tr -Principal $pr -Settings $se -Force | Out-Null
        if (Test-Autostart) { Write-Host '  ✓ автозапуск включён: при входе в Windows поднимется то, что у тебя сейчас включено' -ForegroundColor Green }
        else { Write-Host '  ✗ не удалось создать задачу автозапуска' -ForegroundColor Red }
    } else {
        Unregister-ScheduledTask -TaskName $Task -Confirm:$false -ErrorAction SilentlyContinue
        Write-Host '  ✓ автозапуск выключен' -ForegroundColor Yellow
    }
}

# при входе в Windows: восстановить то, что было включено
function Invoke-Auto {
    if (St-Get 'want_dns' $false)  { Set-Dns (St-Get 'dns_provider' 'cloudflare') }
    if (St-Get 'want_warp' $false) { Enable-Warp }
    elseif (St-Get 'want_dpi' $false) { Start-Bypass }
    if (St-Get 'want_tg' $false)   { Start-Tg }
    if ((St-Get 'want_lhm' $false) -and (Get-LhmExe)) { Start-Lhm }
}

# =====================================================================
#  ПОЛНЫЙ СБРОС - вернуть всё как было
# =====================================================================
function Reset-All {
    Write-Host '  Полный сброс: остановит все модули, вернёт DNS, уберёт драйверы и автозапуск. Продолжить? [Y/n] ' -NoNewline -ForegroundColor Yellow
    if (([Console]::ReadLine()) -match '^(n|н)') { return }

    Write-Host '  » DPI-обход (goodbyedpi / winws)...' -ForegroundColor Soft
    Stop-Bypass -Quiet
    Write-Host '  » TG WS Proxy...' -ForegroundColor Soft
    Stop-Tg -Quiet
    Stop-Lhm -Quiet
    sc.exe stop R0LibreHardwareMonitor | Out-Null; sc.exe delete R0LibreHardwareMonitor | Out-Null
    Write-Host '  » WARP: отключаю и удаляю регистрацию...' -ForegroundColor Soft
    $c = Get-WarpCli
    if ($c) { & $c disconnect | Out-Null; & $c registration delete | Out-Null; & $c delete | Out-Null }
    Write-Host '  » драйверы WinDivert...' -ForegroundColor Soft
    Start-Sleep 1
    foreach ($n in 'WinDivert', 'WinDivert14', 'WinDivert1.4', 'WinDivert2.2') { sc.exe stop $n | Out-Null; sc.exe delete $n | Out-Null }
    sc.exe stop zapret | Out-Null
    Write-Host '  » DNS: автоматический на всех адаптерах, DoH-записи удалены...' -ForegroundColor Soft
    Reset-DNS -Quiet
    ipconfig.exe /flushdns | Out-Null
    Write-Host '  » автозапуск и сохранённые настройки...' -ForegroundColor Soft
    Unregister-ScheduledTask -TaskName $Task -Confirm:$false -ErrorAction SilentlyContinue
    if (Test-Path $State) { Remove-Item $State -Force }
    foreach ($f in 'eternity.mode', 'eternity.engine', 'eternity.strategy') { $x = Join-Path $Root $f; if (Test-Path $x) { Remove-Item $x -Force } }

    Write-Host '  Удалить скачанные файлы (zapret, goodbyedpi, TG WS Proxy в C:\ProgramData\Eternity)? [y/N] ' -NoNewline -ForegroundColor Yellow
    if (([Console]::ReadLine()) -match '^(y|д)') {
        Remove-Item $Data -Recurse -Force -ErrorAction SilentlyContinue
        Write-Host '  ✓ файлы удалены' -ForegroundColor Green
    }
    if ($c) {
        Write-Host '  Удалить клиент Cloudflare WARP из системы? [y/N] ' -NoNewline -ForegroundColor Yellow
        if (([Console]::ReadLine()) -match '^(y|д)') {
            & winget.exe uninstall --id Cloudflare.Warp -e --silent | Out-Null
            Write-Host '  ✓ WARP удалён' -ForegroundColor Green
        }
    }

    Start-Sleep 2
    if (Resolve-DnsName 'example.com' -Type A -DnsOnly -ErrorAction SilentlyContinue) { Write-Host '  ✓ всё сброшено, DNS работает' -ForegroundColor Green }
    else {
        Write-Host '  ! сброс выполнен, но DNS пока не отвечает. Переподключи Wi-Fi/кабель,' -ForegroundColor Yellow
        Write-Host '    если не поможет - перезагрузи ПК (драйвер WinDivert выгрузится полностью).' -ForegroundColor Yellow
    }
}

# =====================================================================
#  Диагностика
# =====================================================================
function Test-Sites {
    foreach ($h in 'www.youtube.com', 'discord.com', 'www.instagram.com', 'telegram.org') {
        $ip = (Resolve-DnsName $h -Type A -DnsOnly -ErrorAction SilentlyContinue | Where-Object IPAddress | Select-Object -First 1).IPAddress
        if (-not $ip) { Write-Host ('  ✗ {0,-20} DNS не резолвится (блок/подмена DNS - включи пункт 2)' -f $h) -ForegroundColor Red; continue }
        $code = & curl.exe -s -o NUL -m 8 --connect-timeout 5 -w '%{http_code}' "https://$h"
        if ("$code" -match '^\d{3}$' -and "$code" -ne '000') { Write-Host ('  ✓ {0,-20} {1}  ({2})' -f $h, $code, $ip) -ForegroundColor Green }
        else { Write-Host ('  ✗ {0,-20} DNS ok ({1}), но TLS не проходит - блок по SNI/DPI, нужна другая стратегия (пункт 5)' -f $h, $ip) -ForegroundColor Red }
    }
}

# =====================================================================
#  Переключатели меню
# =====================================================================
function Toggle-Dpi {
    if (Test-Running) { Stop-Bypass; St-Set 'want_dpi' $false } else { Start-Bypass }
}
function Toggle-Dns {
    if (Get-DnsKey) { Reset-DNS; St-Set 'want_dns' $false } else { Set-Dns (St-Get 'dns_provider' 'cloudflare') }
}
function Toggle-Tg {
    if (Test-Tg) { Stop-Tg; St-Set 'want_tg' $false } else { Start-Tg }
}
function Toggle-Warp {
    if ((Get-WarpState) -eq 'on') { Disable-Warp } else { Enable-Warp }
}
function Switch-Engine {
    Stop-Bypass -Quiet
    $new = if ((Get-EngineName) -eq 'zapret') { 'goodbyedpi' } else { 'zapret' }
    St-Set 'engine' $new
    Write-Host "  ✓ движок DPI: $new (включи пунктом 1; для zapret сначала 5 - автоподбор)" -ForegroundColor Green
}
function Switch-Mode {
    $new = if ((Get-Mode) -eq '5') { '9' } else { '5' }
    St-Set 'mode' $new
    Write-Host "  ✓ режим goodbyedpi теперь -$new" -ForegroundColor Green
    if ((Test-Running) -and (Get-EngineName) -eq 'goodbyedpi') { Start-Bypass }
}
function Update-Modules {
    $wasDpi = Test-Running; $wasTg = Test-Tg
    Stop-Bypass -Quiet; Stop-Tg -Quiet
    if ((Get-EngineName) -eq 'zapret') { [void](Install-Zapret) } else { [void](Install-Engine) }
    if (Get-TgExe) { [void](Install-Tg) }
    if ($wasTg) { Start-Tg }
    if ($wasDpi) { Start-Bypass }
}

# =====================================================================
#  Панель и баннер
# =====================================================================
function Test-Lhm { [bool](Get-Process -Name 'LibreHardwareMonitor' -ErrorAction SilentlyContinue) }
function Get-LhmExe { Get-ChildItem $LhmDir -Recurse -Filter 'LibreHardwareMonitor.exe' -ErrorAction SilentlyContinue | Select-Object -First 1 }

# LibreHardwareMonitor нужен для температур CPU/материнки/вентиляторов: у Windows нет открытого API на температуру кристалла
function Install-Lhm {
    Write-Host '  » качаю LibreHardwareMonitor (open source) с GitHub...' -ForegroundColor Soft
    $rel = Get-Release 'LibreHardwareMonitor/LibreHardwareMonitor'
    $asset = $rel.assets | Where-Object name -eq 'LibreHardwareMonitor.zip' | Select-Object -First 1
    if (-not $asset) { Write-Host '  ✗ не удалось получить релиз (GitHub недоступен?)' -ForegroundColor Red; return $false }
    Stop-Lhm -Quiet
    $zip = Join-Path $env:TEMP $asset.name
    Invoke-WebRequest $asset.browser_download_url -OutFile $zip -UseBasicParsing
    if (Test-Path $LhmDir) { Remove-Item $LhmDir -Recurse -Force }
    New-Item -ItemType Directory -Path $LhmDir -Force | Out-Null
    Expand-Archive $zip -DestinationPath $LhmDir -Force
    Remove-Item $zip -Force
    Get-ChildItem $LhmDir -Recurse -File | Unblock-File
    $exe = Get-LhmExe
    if (-not $exe) { Write-Host '  ✗ LibreHardwareMonitor.exe не найден в архиве' -ForegroundColor Red; return $false }
    # стартовать свёрнутым в трей
    $cfg = Join-Path $exe.DirectoryName 'LibreHardwareMonitor.config'
    $xml = '<?xml version="1.0" encoding="utf-8"?><configuration><appSettings>' +
           '<add key="startMinMenuItem" value="true" /><add key="minTrayMenuItem" value="true" />' +
           '<add key="minCloseMenuItem" value="true" /></appSettings></configuration>'
    Set-Content -Path $cfg -Value $xml -Encoding UTF8
    Write-Host '  ✓ LibreHardwareMonitor установлен' -ForegroundColor Green
    $true
}

function Start-Lhm([switch]$Yes) {
    if (-not (Get-LhmExe)) {
        if (-not $Yes) {
            Write-Host '  LibreHardwareMonitor ставит драйвер для чтения датчиков (антивирус может ругаться). Установить? [y/N] ' -NoNewline -ForegroundColor Yellow
            if (([Console]::ReadLine()) -notmatch '^(y|д)') { return }
        }
        if (-not (Install-Lhm)) { return }
    }
    if (-not (Test-Lhm)) {
        $exe = Get-LhmExe
        Start-Process $exe.FullName -WorkingDirectory $exe.DirectoryName -WindowStyle Minimized
        for ($i = 0; $i -lt 10; $i++) { Start-Sleep 1; if (@(Get-LhmSensors).Count) { break } }
    }
    if (-not (Test-Lhm)) { Write-Host '  ✗ LibreHardwareMonitor не запустился (антивирус?)' -ForegroundColor Red; return }
    St-Set 'want_lhm' $true
    $all = @(Get-LhmSensors)
    $cpuT = @($all | Where-Object { $_.SensorType -eq 'Temperature' -and $_.Identifier -match '/(intel|amd)cpu/' })
    if ($cpuT.Count) { Write-Host "  ✓ датчики работают: найдено $($all.Count), температур CPU: $($cpuT.Count)" -ForegroundColor Green }
    elseif ($all.Count) {
        Write-Host "  ! датчики запущены ($($all.Count)), но температуры CPU нет. Открой LibreHardwareMonitor из трея и посмотри," -ForegroundColor Yellow
        Write-Host '    что он видит; для CPU может понадобиться драйвер PawnIO (https://pawnio.eu) - поставь и перезапусти датчики.' -ForegroundColor Yellow
    } else {
        Write-Host '  ! LibreHardwareMonitor запущен, но данные по WMI не отдаёт (нужны права администратора и драйвер).' -ForegroundColor Yellow
    }
}
function Stop-Lhm([switch]$Quiet) {
    Get-Process -Name 'LibreHardwareMonitor' -ErrorAction SilentlyContinue | Stop-Process -Force
    if (-not $Quiet) { Write-Host '  ✓ датчики остановлены' -ForegroundColor Yellow }
}

function Toggle-Lhm {
    if (Test-Lhm) { Stop-Lhm; St-Set 'want_lhm' $false } else { Start-Lhm }
}

# --- чтение датчиков ---
function Get-LhmSensors {
    foreach ($ns in 'root\LibreHardwareMonitor', 'root\OpenHardwareMonitor') {
        $s = @(Get-CimInstance -Namespace $ns -ClassName Sensor -ErrorAction SilentlyContinue)
        if ($s.Count) { return $s }
    }
    @()
}

function Get-NvidiaInfo {
    $exe = (Get-Command nvidia-smi.exe -ErrorAction SilentlyContinue).Source
    if (-not $exe) {
        $exe = Join-Path $env:ProgramFiles 'NVIDIA Corporation\NVSMI\nvidia-smi.exe'
        if (-not (Test-Path $exe)) { return $null }
    }
    $q = 'temperature.gpu,utilization.gpu,memory.used,memory.total,power.draw,fan.speed,clocks.gr'
    $line = (& $exe "--query-gpu=$q" '--format=csv,noheader,nounits' | Select-Object -First 1)
    if (-not $line) { return $null }
    $v = $line -split '\s*,\s*'
    function num($s) { $d = 0.0; if ([double]::TryParse("$s".Trim(), [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$d)) { $d } else { $null } }
    [pscustomobject]@{ Temp = (num $v[0]); Load = (num $v[1]); MemUsed = (num $v[2]); MemTotal = (num $v[3]); Power = (num $v[4]); Fan = (num $v[5]); Clock = (num $v[6]) }
}

function Get-DiskTemps {
    $res = New-Object System.Collections.ArrayList
    foreach ($d in (Get-PhysicalDisk -ErrorAction SilentlyContinue)) {
        $rc = $d | Get-StorageReliabilityCounter -ErrorAction SilentlyContinue
        $null = $res.Add([pscustomobject]@{
            Name = "$($d.FriendlyName)"; Media = "$($d.MediaType)"; Bus = "$($d.BusType)"
            Temp = $rc.Temperature; Wear = $rc.Wear; Health = "$($d.HealthStatus)"
        })
    }
    $res
}

function TempColor([double]$c) { if ($c -lt 60) { 'Bar1' } elseif ($c -lt 80) { 'Bar2' } else { 'Bar3' } }
function TempSegs([double]$c, $extra = '') {
    $o = New-Object System.Collections.ArrayList
    $null = $o.Add((S ('{0,3:N0}°C' -f $c) (TempColor $c)))
    $o.AddRange($(BarSegs $c 12 -NoPct))
    if ($extra) { $null = $o.Add((S "  $extra" 'White')) }
    , $o
}
function Cut($s, $n) { if ("$s".Length -gt $n) { "$s".Substring(0, $n - 1) + '…' } else { "$s" } }

# сегменты для вставки температуры справа от строки: "  52°C  extra"
function InlineTemp($c, $extra = '') {
    $o = New-Object System.Collections.ArrayList
    $null = $o.Add((S '  ' 'Gray'))
    $null = $o.Add((S ('{0:N0}°C' -f [double]$c) (TempColor ([double]$c))))
    if ($extra) { $null = $o.Add((S "  $extra" 'Gray')) }
    $o
}

# все показания одним объектом: CPU/GPU/диски по буквам/материнка/вентиляторы
function Get-SensorData {
    $r = [pscustomobject]@{ CpuT = $null; CpuLoad = $null; CpuPow = $null; GpuT = $null; GpuLoad = $null; GpuPow = $null
                            GpuFan = $null; VramUsed = $null; VramTotal = $null; Disk = @{}; Board = $null; BoardName = ''; Fans = @() }
    $lh = @(Get-LhmSensors)
    $temp = @($lh | Where-Object { $_.SensorType -eq 'Temperature' })

    if ($lh.Count) {
        $ct = @($temp | Where-Object { $_.Identifier -match '/(intel|amd)cpu/' })
        $pk = $ct | Where-Object { $_.Name -match 'Package|Tctl|Tdie|Total' } | Select-Object -First 1
        if ($pk) { $r.CpuT = [double]$pk.Value } elseif ($ct.Count) { $r.CpuT = [double](($ct | Measure-Object Value -Maximum).Maximum) }
        $cl = $lh | Where-Object { $_.SensorType -eq 'Load' -and $_.Identifier -match '/(intel|amd)cpu/' -and $_.Name -match 'Total' } | Select-Object -First 1
        if ($cl) { $r.CpuLoad = [double]$cl.Value }
        $cp = $lh | Where-Object { $_.SensorType -eq 'Power' -and $_.Identifier -match '/(intel|amd)cpu/' -and $_.Name -match 'Package' } | Select-Object -First 1
        if ($cp) { $r.CpuPow = [double]$cp.Value }
    }
    if ($null -eq $r.CpuLoad) { $r.CpuLoad = [double](Get-CimInstance Win32_Processor | Select-Object -First 1).LoadPercentage }

    $g = Get-NvidiaInfo
    if ($g) {
        $r.GpuT = $g.Temp; $r.GpuLoad = $g.Load; $r.GpuPow = $g.Power; $r.GpuFan = $g.Fan; $r.VramUsed = $g.MemUsed; $r.VramTotal = $g.MemTotal
    } else {
        $gs = $temp | Where-Object { $_.Identifier -match 'gpu' } | Select-Object -First 1
        if ($gs) { $r.GpuT = [double]$gs.Value }
    }

    # диски: температура физического диска -> по букве тома (опрос медленный - кэш на 20 с)
    if (-not $script:DiskCache -or ((Get-Date) - $script:DiskCacheAt).TotalSeconds -gt 20) {
        $byNum = @{}
        foreach ($pd in (Get-PhysicalDisk -ErrorAction SilentlyContinue)) {
            $rc = $pd | Get-StorageReliabilityCounter -ErrorAction SilentlyContinue
            $byNum["$($pd.DeviceId)"] = [pscustomobject]@{ Temp = $rc.Temperature; Wear = $rc.Wear; Name = "$($pd.FriendlyName)" }
        }
        $map = @{}
        foreach ($part in (Get-Partition -ErrorAction SilentlyContinue | Where-Object DriveLetter)) {
            $map["$($part.DriveLetter):"] = $byNum["$($part.DiskNumber)"]
        }
        $script:DiskCache = $map; $script:DiskCacheAt = Get-Date
    }
    $r.Disk = $script:DiskCache
    if ($lh.Count) {
        $mb = $temp | Where-Object { $_.Identifier -match '/lpc/' -and [double]$_.Value -gt 0 } | Sort-Object { [double]$_.Value } -Descending | Select-Object -First 1
        if ($mb) { $r.Board = [double]$mb.Value; $r.BoardName = "$($mb.Name)" }
        $r.Fans = @($lh | Where-Object { $_.SensorType -eq 'Fan' -and [double]$_.Value -gt 0 } | Sort-Object { [double]$_.Value } -Descending | Select-Object -First 3 | ForEach-Object { [double]$_.Value })
    }
    $r
}

function Get-Panel {
    if (-not $script:CpuObj) { $script:CpuObj = Get-CimInstance Win32_Processor | Select-Object -First 1 }
    $cpu = $script:CpuObj
    if (-not $script:GpuName) { $script:GpuName = (Get-CimInstance Win32_VideoController | Select-Object -First 1).Name }
    $gpuN = $script:GpuName
    $os  = Get-CimInstance Win32_OperatingSystem
    $ramT = $os.TotalVisibleMemorySize * 1KB; $ramU = $ramT - $os.FreePhysicalMemory * 1KB
    $pf  = Get-CimInstance Win32_PageFileUsage | Select-Object -First 1
    $up  = (Get-Date) - $os.LastBootUpTime
    $cpuName = ($cpu.Name -replace '\(R\)|\(TM\)|CPU|Processor', '' -replace '\s+@.*$', '' -replace '\s+', ' ').Trim()
    $kind = if ($gpuN -match 'NVIDIA|Radeon RX|Radeon Pro|Arc ') { 'Discrete' } else { 'Integrated' }

    $sd = Get-SensorData
    $hw = New-Object System.Collections.ArrayList
    $cpuTxt = $cpuName
    $cs = New-Object System.Collections.ArrayList
    $null = $cs.Add((S $cpuTxt 'White'))
    $cx = @(); if ($null -ne $sd.CpuLoad) { $cx += ('load {0:N0}%' -f $sd.CpuLoad) }; if ($sd.CpuPow) { $cx += ('{0:N0} W' -f $sd.CpuPow) }
    if ($ShowCpuTemp -and $null -ne $sd.CpuT) { $cs.AddRange($(InlineTemp $sd.CpuT ($cx -join '  '))) }
    elseif ($cx.Count) { $null = $cs.Add((S ('  ' + ($cx -join '  ')) 'Gray')) }
    $null = $hw.Add((Row 'CPU' $cs))
    $gs = New-Object System.Collections.ArrayList
    $null = $gs.Add((S "$gpuN" 'White'))
    if ($null -ne $sd.GpuT) {
        $gx = @(); if ($null -ne $sd.GpuLoad) { $gx += ('load {0:N0}%' -f $sd.GpuLoad) }; if ($sd.GpuPow) { $gx += ('{0:N0} W' -f $sd.GpuPow) }
        $gs.AddRange($(InlineTemp $sd.GpuT ($gx -join '  ')))
    }
    $null = $hw.Add((Row 'GPU' $gs))
    if ($sd.VramTotal) {
        $null = $hw.Add((Row 'VRAM' (WithBar ('{0:N2} / {1:N2} GiB' -f ($sd.VramUsed / 1024), ($sd.VramTotal / 1024)) ($sd.VramUsed / $sd.VramTotal * 100))))
    }
    $null = $hw.Add((Row 'RAM' (WithBar ('{0} GiB / {1} GiB' -f (Gib $ramU), (Gib $ramT)) ($ramU / $ramT * 100))))
    if ($pf) {
        $pct = $pf.CurrentUsage / [math]::Max($pf.AllocatedBaseSize, 1) * 100
        $null = $hw.Add((Row 'SWAP' (WithBar ('{0:N2} MiB / {1:N2} GiB' -f $pf.CurrentUsage, ($pf.AllocatedBaseSize / 1024)) $pct)))
    }
    foreach ($d in (Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3')) {
        $u = $d.Size - $d.FreeSpace
        $dv = WithBar ('{0}\ {1} GiB / {2} GiB' -f $d.DeviceID, (Gib $u), (Gib $d.Size)) ($u / $d.Size * 100)
        $di = $sd.Disk[$d.DeviceID]
        if ($di -and $null -ne $di.Temp -and $di.Temp -gt 0) {
            $dx = ''; if ($null -ne $di.Wear -and $di.Wear -gt 0) { $dx = 'износ {0}%' -f $di.Wear }
            $dv.AddRange($(InlineTemp $di.Temp $dx))
        }
        $null = $hw.Add((Row 'DRIVE' $dv))
    }

    if ($null -ne $sd.Board) { $bs = New-Object System.Collections.ArrayList; $null = $bs.Add((S $sd.BoardName 'White')); $bs.AddRange($(InlineTemp $sd.Board)); $null = $hw.Add((Row 'BOARD' $bs)) }
    if ($sd.Fans.Count) {
        $fx = ($sd.Fans | ForEach-Object { '{0:N0} rpm' -f $_ }) -join '  '
        if ($null -ne $sd.GpuFan) { $fx += ('  GPU {0:N0}%' -f $sd.GpuFan) }
        $null = $hw.Add((Row 'FANS' $fx))
    }

    # --- модули ---
    $mods = New-Object System.Collections.ArrayList
    $eng = Get-EngineName
    if (Test-Running) {
        $detail = if ($eng -eq 'zapret') { "zapret [$(St-Get 'strategy' '?')]" } else { "goodbyedpi (-$(Get-Mode))" }
        $null = $mods.Add((Row 'DPI' "● $detail" 'Green'))
    } else { $null = $mods.Add((Row 'DPI' "○ выкл  (движок: $eng)" 'Red')) }
    $dk = Get-DnsKey
    if ($dk) {
        $dp = $DnsProviders[$dk]; $dip = $dp.Servers[0]
        if (Test-DohRegistered $dip) { $null = $mods.Add((Row 'DNS' "● $($dp.Name)  DoH $dip" 'Green')) }
        elseif ($dp.Doh) { $null = $mods.Add((Row 'DNS' "● $($dp.Name) $dip  БЕЗ шифрования (DoH не включён)" 'Yellow')) }
        else { $null = $mods.Add((Row 'DNS' "● $($dp.Name)  $dip  (обычный DNS)" 'Green')) }
    } else { $null = $mods.Add((Row 'DNS' '○ системный (подмена DNS возможна)' 'Red')) }
    if (Test-Tg) { $null = $mods.Add((Row 'TG PROXY' '● работает  127.0.0.1:1443' 'Green')) }
    elseif (Get-TgExe) { $null = $mods.Add((Row 'TG PROXY' '○ выкл' 'Red')) }
    else { $null = $mods.Add((Row 'TG PROXY' '○ не установлен (пункт 3)' 'Yellow')) }
    switch (Get-WarpState) {
        'on'    { $null = $mods.Add((Row 'WARP' '● подключён' 'Green')) }
        'off'   { $null = $mods.Add((Row 'WARP' '○ отключён' 'Red')) }
        default { $null = $mods.Add((Row 'WARP' '○ не установлен (пункт 4)' 'Yellow')) }
    }
    if (Test-Lhm) { $null = $mods.Add((Row 'SENSORS' '● LibreHardwareMonitor' 'Green')) }
    elseif (Get-LhmExe) { $null = $mods.Add((Row 'SENSORS' '○ выкл' 'Red')) }
    else { $null = $mods.Add((Row 'SENSORS' '○ не установлен (пункт H)' 'Yellow')) }
    if (Test-Autostart) { $null = $mods.Add((Row 'AUTOSTART' '● вкл (при входе в Windows)' 'Green')) } else { $null = $mods.Add((Row 'AUTOSTART' '○ выкл' 'Red')) }

    $login = (Get-Process explorer -ErrorAction SilentlyContinue | Select-Object -First 1).StartTime
    if (-not $login) { $login = $os.LastBootUpTime }
    $ses = New-Object System.Collections.ArrayList
    $null = $ses.Add((Row 'LOGIN' ('{0} // {1:yyyy-MM-dd HH:mm:ss}' -f $env:USERNAME, $login)))

    $ud = New-Object System.Collections.ArrayList
    $null = $ud.Add((Row 'UPTIME' ('{0} hours, {1} mins' -f [int][math]::Floor($up.TotalHours), $up.Minutes)))
    $null = $ud.Add((Row 'DATE' (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')))

    $hour = (Get-Date).Hour
    $hi = if ($hour -lt 6) { 'Доброй ночи' } elseif ($hour -lt 12) { 'Доброе утро' } elseif ($hour -lt 18) { 'Добрый день' } else { 'Добрый вечер' }

    $o = New-Object System.Collections.ArrayList
    $blank = Ln (S '')
    $null = $o.Add((Ln (S 'Hey, ') (S $env:USERNAME 'Soft')))
    $null = $o.Add($blank)
    $o.AddRange(@(Box 'Hardware' $hw 'Cyan' 45)); $null = $o.Add($blank)
    $o.AddRange(@(Box 'Modules' $mods 'Cyan' 45)); $null = $o.Add($blank)
    $o.AddRange(@(Box 'Session' $ses 'Lab2' 45)); $null = $o.Add($blank)
    $o.AddRange(@(Box 'Uptime / Date' $ud 'Cyan2' 46)); $null = $o.Add($blank)
    $null = $o.Add((Ln (S "$hi! $($env:USERNAME)." 'Orange')))
    $null = $o.Add($blank)
    $dots = New-Object System.Collections.ArrayList; foreach ($k in 1..8) { $null = $dots.Add((S '●  ' "dot$k")) }
    $null = $o.Add((Ln (S ' ') $dots.ToArray()))
    , $o
}

function Show-Banner([switch]$NoClear) {
    if (-not $Preview -and -not $NoClear) { Clear-Host }
    $panel = Get-Panel
    Write-Host ''
    Write-Host "  Eternity v$Version" -ForegroundColor Cyan
    Write-Host ''
    $off = 2
    $n = [math]::Max($Art.Count + $off, $panel.Count)
    for ($i = 0; $i -lt $n; $i++) {
        Write-Host '  ' -NoNewline
        $ai = $i - $off
        if ($ai -ge 0 -and $ai -lt $Art.Count) {
            Write-Art $Art[$ai]
            Write-Host (' ' * ($ArtW - (VLen $Art[$ai]) + $Gap)) -NoNewline
        } else { Write-Host (' ' * ($ArtW + $Gap)) -NoNewline }
        if ($i -lt $panel.Count) {
            foreach ($s in $panel[$i]) {
                if ($s[0] -is [array]) { foreach ($z in $s) { Write-Host $z[0] -NoNewline -ForegroundColor $z[1] } }
                else { Write-Host $s[0] -NoNewline -ForegroundColor $s[1] }
            }
        }
        Write-Host ''
    }
    Write-Host ''
}

function Show-Menu {
    $items = @(
        @('1', 'DPI-обход',                      (Test-Running)),
        @('2', $(if (Get-DnsKey) { 'DNS: ' + $DnsProviders[(Get-DnsKey)].Name } else { 'DNS (вкл/выкл)' }), [bool](Get-DnsKey)),
        @('D', 'Выбрать DNS',                    $null),
        @('A', 'Автоподбор DNS',                 $null),
        @('G', 'Обновления',                     $null),
        @('3', 'TG WS Proxy',                    (Test-Tg)),
        @('4', 'Cloudflare WARP',                ((Get-WarpState) -eq 'on')),
        @('5', 'Автоподбор DPI',                 $null),
        @('6', "Движок: $(Get-EngineName)",      $null),
        @('7', "Режим gdpi: -$(Get-Mode)",       $null),
        @('8', 'Автозапуск',                     (Test-Autostart)),
        @('9', 'Тест сайтов',                    $null),
        @('T', 'TG: добавить прокси',            $null),
        @('U', 'Обновить модули',                $null),
        @('S', "Тема: $(Get-ThemeKey)",            $null),
        @('M', 'Режим терминала', (St-Get 'mode_terminal' $false)),
        @('H', 'Датчики (LHM)', (Test-Lhm)),
        @('R', 'СБРОС ВСЕГО',                    $null),
        @('0', 'Выход',                          $null)
    )
    $n = 0
    foreach ($it in $items) {
        if ($n % 4 -eq 0) { Write-Host '  ' -NoNewline }
        $kc = if ($it[0] -eq 'R') { 'Red' } else { 'Cyan' }
        Write-Host "[$($it[0])] " -NoNewline -ForegroundColor $kc
        Write-Host $it[1].PadRight(20) -NoNewline -ForegroundColor Gray
        if ($it[2] -eq $true) { Write-Host 'ВКЛ ' -NoNewline -ForegroundColor Green }
        elseif ($it[2] -eq $false) { Write-Host 'выкл' -NoNewline -ForegroundColor DarkGray }
        else { Write-Host '    ' -NoNewline }
        Write-Host '  ' -NoNewline
        $n++
        if ($n % 4 -eq 0) { Write-Host '' }
    }
    if ($n % 4 -ne 0) { Write-Host '' }
    Write-Host ''
}

# =====================================================================
#  ОБНОВЛЕНИЯ (GitHub: $Repo) - проверка при запуске и по пункту G
#  Источник: последний релиз (tag), если релизов нет - файл VERSION в ветке main.
#  Скачанный Eternity.ps1 проверяется парсером PowerShell, старый сохраняется как .bak
# =====================================================================
function ConvertTo-Ver($s) {
    $x = "$s".Trim().TrimStart('v', 'V'); $v = $null
    if ([version]::TryParse($x, [ref]$v)) { $v } else { $null }
}

function Get-RemoteVersion {
    $h = @{ 'User-Agent' = 'Eternity' }
    try {
        $r = Invoke-RestMethod "https://api.github.com/repos/$Repo/releases/latest" -Headers $h -TimeoutSec 5
        if ($r.tag_name) { return [pscustomobject]@{ Tag = "$($r.tag_name)"; Ref = "$($r.tag_name)"; Notes = "$($r.body)" } }
    } catch {}
    try {
        $v = Invoke-RestMethod "https://raw.githubusercontent.com/$Repo/main/VERSION" -Headers $h -TimeoutSec 5
        if ($v) { return [pscustomobject]@{ Tag = "$v".Trim(); Ref = 'main'; Notes = '' } }
    } catch {}
    $null
}

function Update-Self([string]$Ref) {
    $base = "https://raw.githubusercontent.com/$Repo/$Ref"
    $tmp = Join-Path $env:TEMP 'Eternity.update.ps1'
    Write-Host "  » качаю Eternity.ps1 ($Ref)..." -ForegroundColor Soft
    try { Invoke-WebRequest "$base/Eternity.ps1" -OutFile $tmp -UseBasicParsing -TimeoutSec 40 -Headers @{ 'User-Agent' = 'Eternity' } }
    catch { Write-Host "  ✗ не удалось скачать: $($_.Exception.Message)" -ForegroundColor Red; return }
    $txt = [IO.File]::ReadAllText($tmp, [Text.Encoding]::UTF8)
    $errs = $null
    [void][System.Management.Automation.Language.Parser]::ParseInput($txt, [ref]$null, [ref]$errs)
    if ($errs.Count -or $txt -notmatch 'Eternity' -or $txt.Length -lt 20000) {
        Write-Host '  ✗ скачанный файл не прошёл проверку (повреждён или не Eternity) - обновление отменено' -ForegroundColor Red
        return
    }
    Copy-Item $PSCommandPath "$PSCommandPath.bak" -Force
    [IO.File]::WriteAllText($PSCommandPath, $txt, (New-Object System.Text.UTF8Encoding($true)))
    try {
        $bat = Join-Path $env:TEMP 'Eternity.update.bat'
        Invoke-WebRequest "$base/Eternity.bat" -OutFile $bat -UseBasicParsing -TimeoutSec 20 -Headers @{ 'User-Agent' = 'Eternity' }
        $b = [IO.File]::ReadAllText($bat); if ($b -match 'Eternity\.ps1') { Copy-Item $bat (Join-Path $Root 'Eternity.bat') -Force }
    } catch {}
    St-Set 'update_last' (Get-Date).ToString('o')
    Write-Host '  ✓ обновлено. Старая версия сохранена как Eternity.ps1.bak. Перезапускаю...' -ForegroundColor Green
    Start-Sleep 2
    $self = "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`""
    if (Get-Command wt.exe -ErrorAction SilentlyContinue) { Start-Process wt.exe -ArgumentList "--size $WinW,$WinH -p Eternity powershell.exe $self" }
    else { Start-Process powershell -ArgumentList $self }
    Set-TermBg $null
    exit
}

function Check-Update([switch]$Manual) {
    if (-not $Manual) {
        if (-not (St-Get 'update_check' $true)) { return }
        $last = St-Get 'update_last' $null
        try { if ($last -and ((Get-Date) - [datetime]$last).TotalMinutes -lt 30) { return } } catch {}
    }
    St-Set 'update_last' (Get-Date).ToString('o')
    $rv = Get-RemoteVersion
    if (-not $rv) {
        if ($Manual) { Write-Host '  ! не удалось связаться с GitHub (нет сети или репозиторий закрыт)' -ForegroundColor Yellow }
        return
    }
    $new = ConvertTo-Ver $rv.Tag; $cur = ConvertTo-Ver $Version
    if (-not $new -or -not $cur) {
        if ($Manual) { Write-Host "  ! не удалось сравнить версии: удалённая '$($rv.Tag)', локальная '$Version'" -ForegroundColor Yellow }
        return
    }
    if ($new -le $cur) {
        if ($Manual) { Write-Host "  ✓ у тебя последняя версия ($Version)" -ForegroundColor Green }
        return
    }
    Write-Host ''
    Write-Host "  ⬆ Доступна новая версия Eternity: $($rv.Tag) (у тебя $Version)" -ForegroundColor Orange
    if ($rv.Notes) {
        $n = ($rv.Notes -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -First 6) -join "`n    "
        Write-Host "    $n" -ForegroundColor DarkGray
    }
    Write-Host '  Обновить сейчас? [Y/n] ' -NoNewline -ForegroundColor Yellow
    if (([Console]::ReadLine()) -notmatch '^(n|н)') { Update-Self $rv.Ref }
}

# =====================================================================
#  РЕЖИМ ТЕРМИНАЛА: тот же промпт принимает обычные команды PowerShell
#  выход из режима: menu | eternity | меню      закрыть программу: exit
#  служебные: banner (показать баннер ещё раз), cls
# =====================================================================
# ввод строки через PSReadLine: Tab - автодополнение, стрелки - история, подсветка синтаксиса.
# Если модуль/консоль недоступны - обычное чтение строки.
$script:PsrlReady = $null
function Initialize-PsReadLine {
    if ($null -ne $script:PsrlReady) { return $script:PsrlReady }
    $script:PsrlReady = $false
    try {
        if ($Host.Name -ne 'ConsoleHost') { return $false }
        Import-Module PSReadLine -ErrorAction Stop
        $e = [char]27
        $c = { param($k) $v = $Pal[$k]; "$e[38;2;$($v[0]);$($v[1]);$($v[2])m" }
        Set-PSReadLineOption -BellStyle None -HistoryNoDuplicates -MaximumHistoryCount 4000
        Set-PSReadLineOption -Colors @{
            Command   = (& $c 'Cyan_n')
            Parameter = (& $c 'Soft')
            String    = (& $c 'Green')
            Number    = (& $c 'Yellow')
            Variable  = (& $c 'Pink2')
            Operator  = (& $c 'Gray')
            Type      = (& $c 'Title')
            Comment   = (& $c 'DarkGray')
            Keyword   = (& $c 'Pink')
            Member    = (& $c 'White')
            Error     = (& $c 'Red')
        }
        Set-PSReadLineKeyHandler -Key Tab -Function MenuComplete          # Tab - меню вариантов
        Set-PSReadLineKeyHandler -Key Shift+Tab -Function TabCompletePrevious
        $script:PsrlReady = $true
    } catch { $script:PsrlReady = $false }
    return $script:PsrlReady
}

function Read-TermLine {
    if (Initialize-PsReadLine) {
        try { return [Microsoft.PowerShell.PSConsoleReadLine]::ReadLine($Host.Runspace, $ExecutionContext) }
        catch { $script:PsrlReady = $false }
    }
    [Console]::ReadLine()
}
function Enter-TermMode {
    St-Set 'mode_terminal' $true
    Show-Banner
    Write-Host '  ● режим терминала ВКЛ - вводи команды PowerShell (cd, dir, ping, git ...).' -ForegroundColor Green
    Write-Host '    Tab - автодополнение, ↑/↓ - история   menu - в меню   banner - баннер   cls - очистить   exit - закрыть' -ForegroundColor DarkGray
    Write-Host ''
    while ($true) {
        Write-Host ("  PS " + (Get-Location).Path + "> ") -NoNewline -ForegroundColor Cyan
        $line = Read-TermLine
        if ($null -eq $line) { break }
        $cmd = $line.Trim()
        if ($cmd -eq '') { continue }
        if ($cmd -match '^(menu|eternity|меню)$') { break }
        if ($cmd -match '^(exit|quit)$') { Set-TermBg $null; exit }
        if ($cmd -match '^(cls|clear)$') { Clear-Host; continue }
        if ($cmd -eq 'banner') { Show-Banner; continue }
        $prev = $ErrorActionPreference
        $ErrorActionPreference = 'Continue'              # в терминале ошибки команд нужно видеть
        try { Invoke-Expression $cmd | Out-Host }
        catch { Write-Host "  $($_.Exception.Message)" -ForegroundColor Red }
        finally { $ErrorActionPreference = $prev }
    }
    St-Set 'mode_terminal' $false
    Write-Host '  ○ режим терминала выключен - возвращаю меню' -ForegroundColor Yellow
}
# ввод в меню: пока ничего не нажато, панель сама обновляется каждые N секунд (температуры, нагрузка, статусы)
$script:LiveRefresh = 0      # секунд между обновлениями панели; 0 = выключено (обычный ввод строки, обновление по Enter)
function Read-MenuLine {
    if ($script:LiveRefresh -le 0) { return [Console]::ReadLine() }     # обычный ввод - как раньше
    $buf = ''
    $last = Get-Date
    $e = [char]27
    while ($true) {
        if ([Console]::KeyAvailable) {
            $k = [Console]::ReadKey($true)
            if ($k.Key -eq 'Enter') { Write-Host ''; return $buf }
            elseif ($k.Key -eq 'Backspace') {
                if ($buf.Length) { $buf = $buf.Substring(0, $buf.Length - 1); Write-Host "`b `b" -NoNewline }
            }
            elseif ($k.KeyChar -and -not [char]::IsControl($k.KeyChar)) { $buf += $k.KeyChar; Write-Host $k.KeyChar -NoNewline }
        } else {
            Start-Sleep -Milliseconds 60
            if ($script:LiveRefresh -gt 0 -and ((Get-Date) - $last).TotalSeconds -ge $script:LiveRefresh) {
                # рисуем в буфер и выводим одним куском - без мерцания
                $sw = New-Object System.IO.StringWriter
                $old = [Console]::Out
                [Console]::SetOut($sw)
                try {
                    Show-Banner -NoClear
                    Show-Menu
                    Write-Host $PromptText -NoNewline -ForegroundColor Cyan
                    Write-Host $buf -NoNewline
                } finally { [Console]::SetOut($old) }
                [Console]::Out.Write("$e[H" + $sw.ToString() + "$e[0J")
                $last = Get-Date
            }
        }
    }
}
# ---------- запуск ----------
if ($Auto) { Invoke-Auto; return }
Apply-Theme

$PromptText = "  PS C:\Users\$($env:USERNAME)> "
$skipWait = $false
if (-not $Preview -and -not $Auto) { Check-Update }
if (-not $Preview -and -not (Get-LhmExe) -and -not (St-Get 'lhm_asked' $false)) {
    St-Set 'lhm_asked' $true
    Write-Host ''
    Write-Host '  Температуру процессора Windows сама не отдаёт - для неё нужен LibreHardwareMonitor (open source).' -ForegroundColor Yellow
    Write-Host '  Он поставит драйвер датчиков; антивирус иногда ругается. Скачать и включить сейчас? [Y/n] ' -NoNewline -ForegroundColor Yellow
    if (([Console]::ReadLine()) -notmatch '^(n|н)') { Start-Lhm -Yes }
    Write-Host '  (позже включить/выключить: пункт H)' -ForegroundColor DarkGray
    Start-Sleep 2
}
if (-not $Preview -and (St-Get 'mode_terminal' $false)) { Enter-TermMode }
Show-Banner
if ($Preview) { Show-Menu; Write-Host $PromptText -NoNewline -ForegroundColor Cyan; Write-Host '_' -ForegroundColor White; return }

while ($true) {
    Show-Menu
    Write-Host $PromptText -NoNewline -ForegroundColor Cyan
    $c = Read-MenuLine
    Write-Host ''
    switch ($c) {
        '1' { Toggle-Dpi }
        '2' { Toggle-Dns }
        '3' { Toggle-Tg }
        '4' { Toggle-Warp }
        '5' { Find-Strategy }
        '6' { Switch-Engine }
        '7' { Switch-Mode }
        '8' { Set-Autostart (-not (Test-Autostart)) }
        '9' { Test-Sites }
        't' { Open-TgLink }
        'u' { Update-Modules }
        's' { Switch-Theme }
        'm' { Enter-TermMode; $skipWait = $true }
        'h' { Toggle-Lhm }
        'd' { Choose-Dns }
        'a' { Find-BestDns }
        'g' { Check-Update -Manual }
        'r' { Reset-All }
        '0' { Set-TermBg $null; exit }
        default { Write-Host '  ? неизвестная команда' -ForegroundColor DarkGray }
    }
    if ($skipWait) { $skipWait = $false }
    else {
        Write-Host ''
        Write-Host '  Enter - обновить' -NoNewline -ForegroundColor DarkGray
        [void][Console]::ReadLine()
    }
    Show-Banner
}
